const rxOf = (dict, boundary) => {
  const ks = Object.keys(dict).sort((a, b) => b.length - a.length);
  const rx = new RegExp(ks.map(k => `(?<![${boundary}])${k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![${boundary}])`).join('|'), 'g');
  return s => s.replace(rx, m => dict[m]);
};
