const tr = s => { s = s.replace(/ /g, ' '); return lang === 'en' ? toEN(s) : toRU(s); };
const LET = /[A-Za-zА-Яа-яЁё]/;
function localize(root) {
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let n = w.nextNode(); n; n = w.nextNode()) {
    if (n.parentNode && n.parentNode.closest && n.parentNode.closest('[data-raw]')) continue;     // user's own words are never translated
    if (n._src === undefined) { if (!LET.test(n.data)) continue; n._src = n.data; }
    const v = tr(n._src); if (n.data !== v) n.data = v;
  }
  (root.querySelectorAll ? root.querySelectorAll('[title]') : []).forEach(e => {
    if (e._srcT === undefined) { const t = e.getAttribute('title'); if (!LET.test(t)) return; e._srcT = t; }
    e.setAttribute('title', tr(e._srcT));
  });
}
